<?php
require __DIR__.'/oyunchu_config.php';
$msg='';
$conn->query("CREATE TABLE IF NOT EXISTS oh_game_settings (game_slug VARCHAR(30) NOT NULL,skey VARCHAR(100) NOT NULL,svalue TEXT NULL,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(game_slug,skey)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$defaults=['xo_name'=>'X-O','xo_logo'=>'⭕','xo_x_color'=>'#00e5ff','xo_o_color'=>'#ff3dbd','xo_win_coins'=>'50','xo_react_coins'=>'1'];
if($_SERVER['REQUEST_METHOD']==='POST'){ga_verify();$keys=array_keys($defaults);$q=$conn->prepare('INSERT INTO oh_game_settings(game_slug,skey,svalue) VALUES(?,?,?) ON DUPLICATE KEY UPDATE svalue=VALUES(svalue)');foreach($keys as $k){$v=trim((string)($_POST[$k]??$defaults[$k]));$slug='xo';$q->bind_param('sss',$slug,$k,$v);$q->execute();} $msg='X-O ayarları yadda saxlanıldı.';ga_audit('oyunchu_xo_settings','oh_game_settings',null,'xo');}
$vals=$defaults;$st=$conn->prepare('SELECT skey,svalue FROM oh_game_settings WHERE game_slug=?');$slug='xo';$st->bind_param('s',$slug);$st->execute();foreach($st->get_result()->fetch_all(MYSQLI_ASSOC) as $r){if(array_key_exists($r['skey'],$vals))$vals[$r['skey']]=$r['svalue'];}
?><!doctype html><html lang="az" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>X-O ayarları</title><script>document.documentElement.setAttribute('data-theme',localStorage.getItem('esevgili_theme')||'dark');</script></head><body><?php include __DIR__.'/oyunchu_sidebar.php';?><main class="ga-main"><div class="ga-top"><b>❌⭕ X-O oyun ayarları</b></div><div class="ga-content"><?php if($msg):?><div class="ga-alert">✅ <?=ga_h($msg)?></div><?php endif;?><form method="post"><div class="ga-card"><h3>🎮 Görünüş və mükafat</h3><?=csrf_field()?><div class="ga-form"><div><label class="ga-label">Oyun adı</label><input class="ga-input" name="xo_name" value="<?=ga_h($vals['xo_name'])?>"></div><div><label class="ga-label">Logo / emoji / URL</label><input class="ga-input" name="xo_logo" value="<?=ga_h($vals['xo_logo'])?>"></div><div><label class="ga-label">X rəngi</label><input class="ga-input" type="text" name="xo_x_color" value="<?=ga_h($vals['xo_x_color'])?>"></div><div><label class="ga-label">O rəngi</label><input class="ga-input" type="text" name="xo_o_color" value="<?=ga_h($vals['xo_o_color'])?>"></div><div><label class="ga-label">Onlayn qələbə coin</label><input class="ga-input" type="number" min="0" name="xo_win_coins" value="<?=ga_h($vals['xo_win_coins'])?>"></div><div><label class="ga-label">Emoji-reaksiya bonusu (otaq başına, hər tərəfə 1 dəfə)</label><input class="ga-input" type="number" min="0" name="xo_react_coins" value="<?=ga_h($vals['xo_react_coins'])?>"></div></div><br><button class="ga-btn ga-primary">Yadda saxla</button></div></form></div></main></body></html>
